"use strict";(globalThis.webpackChunkgrc||=[]).push([[39933],{58478(e){e.exports=JSON.parse('{"citeKey":"wu1999designimplementation","slug":"wu-1999-design-implementation-37fd","title":"Design and Implementation of a Java-based Distributed Debugger Supporting PVM and MPI","authors":["X. Wu","Q. Chen","X.-H. Sun"],"venue":"The The 11th ISASTED Interantional Conference on Parallel and Distributed Computing and Systems, Nov. 1999, Cambridge, Massachusetts","type":"Conference","entryType":"inproceedings","date":"November, 1999","year":1999,"era":"iit","month":11,"abstract":"This paper presents a client-server debugging model, describes the design and implementation of a portable, scalable, practical distributed debugger based on this model, and compares it with the related work. The distributed debugger based on the sequential debugger gdb or dbx can efficiently support debugging various PVM and MPI programs, and its interfaces are implemented by Java. Therefore, it meets High Performance Debugging Standard\'s three general goals concerning parallel and distributed debuggers. In addition, it is portable, easy to learn and easy to use.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/1999/wu-1999-design-implementation-37fd.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);